1	package factoryaidroid
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"time"
10	
11		"github.com/entireio/cli/cmd/entire/cli/agent"
12		"github.com/entireio/cli/cmd/entire/cli/textutil"
13		"github.com/entireio/cli/cmd/entire/cli/transcript"
14	)
15	
16	// Compile-time interface assertions.
17	var (
18		_ agent.TranscriptAnalyzer     = (*FactoryAIDroidAgent)(nil)
19		_ agent.TokenCalculator        = (*FactoryAIDroidAgent)(nil)
20		_ agent.SubagentAwareExtractor = (*FactoryAIDroidAgent)(nil)
21		_ agent.HookResponseWriter     = (*FactoryAIDroidAgent)(nil)
22		_ agent.PromptExtractor        = (*FactoryAIDroidAgent)(nil)
23	)
24	
25	// WriteHookResponse outputs the hook response as plain text to stdout.
26	// Factory AI Droid does not parse the JSON systemMessage protocol,
27	// so we write plain text that it displays directly in the terminal.
28	func (f *FactoryAIDroidAgent) WriteHookResponse(message string) error {
29		if _, err := fmt.Fprintln(os.Stdout, message); err != nil {
30			return fmt.Errorf("failed to write hook response: %w", err)
31		}
32		return nil
33	}
34	
35	// HookNames returns the hook verbs Factory AI Droid supports.
36	// These become subcommands: entire hooks factoryai-droid <verb>
37	func (f *FactoryAIDroidAgent) HookNames() []string {
38		return []string{
39			HookNameSessionStart,
40			HookNameSessionEnd,
41			HookNameStop,
42			HookNameUserPromptSubmit,
43			HookNamePreToolUse,
44			HookNamePostToolUse,
45			HookNameSubagentStop,
46			HookNamePreCompact,
47			HookNameNotification,
48		}
49	}
50	
51	// ParseHookEvent translates a Factory AI Droid hook into a normalized lifecycle Event.
52	// Returns nil if the hook has no lifecycle significance.
53	func (f *FactoryAIDroidAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
54		switch hookName {
55		case HookNameSessionStart:
56			return f.parseSessionStart(stdin)
57		case HookNameUserPromptSubmit:
58			return f.parseTurnStart(stdin)
59		case HookNameStop:
60			return f.parseTurnEnd(stdin)
61		case HookNameSessionEnd:
62			return f.parseSessionEnd(stdin)
63		case HookNamePreToolUse:
64			return f.parseSubagentStart(stdin)
65		case HookNamePostToolUse:
66			return f.parseSubagentEnd(stdin)
67		case HookNamePreCompact:
68			return f.parseCompaction(stdin)
69		case HookNameSubagentStop, HookNameNotification:
70			// Acknowledged hooks with no lifecycle action
71			return nil, nil //nolint:nilnil // nil event = no lifecycle action
72		default:
73			return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
74		}
75	}
76	
77	// --- TranscriptAnalyzer ---
78	
79	// GetTranscriptPosition returns the current line count of the JSONL transcript.
80	func (f *FactoryAIDroidAgent) GetTranscriptPosition(path string) (int, error) {
81		_, pos, err := ParseDroidTranscript(path, 0)
82		if err != nil {
83			return 0, err
84		}
85		return pos, nil
86	}
87	
88	// ExtractModifiedFilesFromOffset extracts files modified since a given line offset.
89	func (f *FactoryAIDroidAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
90		lines, currentPos, err := ParseDroidTranscript(path, startOffset)
91		if err != nil {
92			return nil, 0, fmt.Errorf("failed to parse transcript: %w", err)
93		}
94		files := ExtractModifiedFiles(lines)
95		return files, currentPos, nil
96	}
97	
98	// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
99	func (f *FactoryAIDroidAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
100		lines, _, err := ParseDroidTranscript(sessionRef, fromOffset)
101		if err != nil {
102			return nil, fmt.Errorf("failed to parse transcript: %w", err)
103		}
104	
105		var prompts []string
106		for i := range lines {
107			if lines[i].Type != transcript.TypeUser {
108				continue
109			}
110			content := transcript.ExtractUserContent(lines[i].Message)
111			if content != "" {
112				prompts = append(prompts, textutil.StripIDEContextTags(content))
113			}
114		}
115		return prompts, nil
116	}
117	
118	// ExtractSummary extracts the last assistant message as a session summary.
119	func (f *FactoryAIDroidAgent) ExtractSummary(sessionRef string) (string, error) {
120		data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
121		if err != nil {
122			return "", fmt.Errorf("failed to read transcript: %w", err)
123		}
124		lines, _, err := ParseDroidTranscriptFromBytes(data, 0)
125		if err != nil {
126			return "", fmt.Errorf("failed to parse transcript: %w", err)
127		}
128	
129		for i := len(lines) - 1; i >= 0; i-- {
130			if lines[i].Type != transcript.TypeAssistant {
131				continue
132			}
133			var msg transcript.AssistantMessage
134			if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
135				continue
136			}
137			for _, block := range msg.Content {
138				if block.Type == transcript.ContentTypeText && block.Text != "" {
139					return block.Text, nil
140				}
141			}
142		}
143		return "", nil
144	}
145	
146	// --- TokenCalculator ---
147	
148	// CalculateTokenUsage computes token usage from pre-loaded transcript bytes starting at the given line offset.
149	func (f *FactoryAIDroidAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
150		return CalculateTotalTokenUsageFromBytes(transcriptData, fromOffset, "")
151	}
152	
153	// --- SubagentAwareExtractor ---
154	
155	// ExtractAllModifiedFiles extracts files modified by both the main agent and any spawned subagents.
156	func (f *FactoryAIDroidAgent) ExtractAllModifiedFiles(transcriptData []byte, fromOffset int, subagentsDir string) ([]string, error) {
157		return ExtractAllModifiedFilesFromBytes(transcriptData, fromOffset, subagentsDir)
