15	func init() {
16		if env := os.Getenv("E2E_AGENT"); env != "" && env != "factoryai-droid" {
17			return
18		}
19		if _, err := exec.LookPath("droid"); err != nil {
20			return
21		}
22		Register(&Droid{})
23	}
