25	// Droid implements the Agent interface for Factory AI Droid.
26	type Droid struct{}
27	
28	func (d *Droid) Name() string               { return "factoryai-droid" }
29	func (d *Droid) Binary() string             { return "droid" }
30	func (d *Droid) EntireAgent() string        { return "factoryai-droid" }
31	func (d *Droid) PromptPattern() string      { return `>` }
32	func (d *Droid) TimeoutMultiplier() float64 { return 2.0 }
33	
34	func (d *Droid) IsTransientError(out Output, err error) bool {
35		if err == nil {
36			return false
37		}
38		combined := out.Stdout + out.Stderr
39		transientPatterns := []string{
40			"overloaded",
41			"rate limit",
42			"529",
43			"503",
44			"ECONNRESET",
45			"ETIMEDOUT",
46		}
47		for _, p := range transientPatterns {
48			if strings.Contains(combined, p) {
49				return true
50			}
51		}
52		return false
53	}
