55	// droidSettings represents the ~/.factory/settings.json structure used for
56	// BYOK (Bring Your Own Key) configuration.
57	type droidSettings struct {
58		CustomModels []droidCustomModel `json:"customModels,omitempty"`
59	}
60	
61	type droidCustomModel struct {
62		DisplayName    string `json:"displayName"`
63		Model          string `json:"model"`
64		BaseURL        string `json:"baseUrl"`
65		APIKey         string `json:"apiKey"`
66		Provider       string `json:"provider"`
67		MaxOutputToken int    `json:"maxOutputTokens"`
68	}
69	
70	const (
71		// Droid v0.63+ expects custom model selection using custom:<model-id>.
72		// The displayName in settings is not accepted by --model.
73		droidCustomModelDisplayName = "claude-haiku-custom"
74		droidCustomModelBaseID      = "claude-haiku-4-5-20251001"
75		defaultDroidModel           = "custom:" + droidCustomModelBaseID
76	)
77	
78	// DefaultDroidModel returns the default model string for Droid BYOK configuration.
79	// Format is "custom:<baseModelID>" which the Droid API expects for custom model selection.
80	func DefaultDroidModel() string { return defaultDroidModel }
81	
82	func (d *Droid) Bootstrap() error {
83		apiKey := os.Getenv("ANTHROPIC_API_KEY")
84		if apiKey == "" {
85			return nil
86		}
87	
88		home, err := os.UserHomeDir()
89		if err != nil {
90			return fmt.Errorf("get home dir: %w", err)
91		}
92		dir := filepath.Join(home, ".factory")
93		if err := os.MkdirAll(dir, 0o755); err != nil {
94			return fmt.Errorf("mkdir %s: %w", dir, err)
95		}
96	
97		settingsPath := filepath.Join(dir, "settings.json")
98	
99		// Read existing settings to merge (hooks may already be configured
100		// in the repo-local .factory/settings.json, but the global config
101		// at ~/.factory/settings.json might have other pre-existing entries).
102		var settings droidSettings
103		if data, readErr := os.ReadFile(settingsPath); readErr == nil {
104			// Best-effort merge: ignore parse errors and start fresh
105			_ = json.Unmarshal(data, &settings)
106		}
107	
108		// Replace or add the BYOK model entry.
109		byokModel := droidCustomModel{
110			DisplayName:    droidCustomModelDisplayName,
111			Model:          droidCustomModelBaseID,
112			BaseURL:        "https://api.anthropic.com",
113			APIKey:         apiKey,
114			Provider:       "anthropic",
115			MaxOutputToken: 8192,
116		}
117	
118		found := false
119		for i, m := range settings.CustomModels {
120			if m.Model == byokModel.Model {
121				settings.CustomModels[i] = byokModel
122				found = true
123				break
124			}
125		}
126		if !found {
127			settings.CustomModels = append(settings.CustomModels, byokModel)
128		}
129	
130		data, err := json.MarshalIndent(settings, "", "  ")
131		if err != nil {
132			return fmt.Errorf("marshal settings: %w", err)
133		}
134		return os.WriteFile(settingsPath, data, 0o644)
135	}
136	
137	func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
138		cfg := &runConfig{Model: defaultDroidModel}
139		for _, o := range opts {
140			o(cfg)
141		}
142	
143		model := cfg.Model
144		if model == "" {
145			model = defaultDroidModel
146		}
147	
148		args := []string{"exec", "--skip-permissions-unsafe", "--model", model, prompt}
149		displayArgs := []string{"exec", "--skip-permissions-unsafe", "--model", model, fmt.Sprintf("%q", prompt)}
150	
151		cmd := exec.CommandContext(ctx, d.Binary(), args...)
152		cmd.Dir = dir
153		cmd.Stdin = nil
154		cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CI", "GITHUB_ACTIONS")
155		setupProcessGroup(cmd)
156		cmd.WaitDelay = 5 * time.Second
157	
158		var stdout, stderr strings.Builder
159		cmd.Stdout = &stdout
160		cmd.Stderr = &stderr
161	
162		err := cmd.Run()
163		exitCode := 0
164		if err != nil {
165			exitErr := &exec.ExitError{}
166			if errors.As(err, &exitErr) {
167				exitCode = exitErr.ExitCode()
168			} else {
169				exitCode = -1
170			}
171		}
172	
173		return Output{
174			Command:  d.Binary() + " " + strings.Join(displayArgs, " "),
175			Stdout:   stdout.String(),
