func configureDroidRepoSettings(repoDir string) error {
	home, err := os.UserHomeDir()
	if err != nil {
		return fmt.Errorf("get home dir: %w", err)
	}

	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
